node -e "
const db = require('better-sqlite3')('/workspace/world.db');

// 1. Update CI-0006 quantity to 2
db.prepare('UPDATE cart_items SET quantity = 2 WHERE cart_item_id = ? AND cart_id = ?').run('CI-0006', 'CART-user_58b0a2d6');

// 2. Remove CI-0005
db.prepare('DELETE FROM cart_items WHERE cart_item_id = ? AND cart_id = ?').run('CI-0005', 'CART-user_58b0a2d6');

// 3. Update the cart: recalculate subtotal/total and item_ids_json
const remaining = db.prepare('SELECT * FROM cart_items WHERE cart_id = ?').all('CART-user_58b0a2d6');
console.log('Remaining items:');
remaining.forEach(i => console.log(JSON.stringify(i)));

// Get prices for remaining items
let subtotal = 0;
remaining.forEach(item => {
  const prod = db.prepare('SELECT price FROM products WHERE product_id = ?').get(item.product_id);
  subtotal += prod.price * item.quantity;
});

const itemIds = JSON.stringify(remaining.map(i => i.cart_item_id));

// Get current cart to preserve shipping
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
const total = subtotal - cart.discount_amount + cart.shipping_cost + cart.gift_wrap_fee - cart.loyalty_discount;

db.prepare('UPDATE carts SET subtotal = ?, total = ?, item_ids_json = ? WHERE cart_id = ?')
  .run(subtotal, total, itemIds, 'CART-user_58b0a2d6');

// Verify final state
const updatedCart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_58b0a2d6');
console.log('\nUpdated cart:');
console.log(JSON.stringify(updatedCart, null, 2));

const updatedItems = db.prepare('SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = ?').all('CART-user_58b0a2d6');
console.log('\nUpdated cart items:');
updatedItems.forEach(i => console.log(JSON.stringify(i, null, 2)));

db.close();
"

