const db = require('better-sqlite3')('/workspace/world.db');

// Check for shipping-related tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' AND name LIKE '%ship%'\").all();
console.log('Shipping tables:', tables);

// Check for any shipping config or options table
const allTables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table' AND (name LIKE '%config%' OR name LIKE '%option%' OR name LIKE '%setting%' OR name LIKE '%shipping%' OR name LIKE '%delivery%')\").all();
console.log('Config/option tables:', allTables);

// Check promotions table for shipping promos
const promos = db.prepare('SELECT * FROM promotions').all();
console.log('\nPromotions:', JSON.stringify(promos, null, 2));

// Check carts table schema
const cartSchema = db.prepare(\"PRAGMA table_info(carts)\").all();
console.log('\nCarts schema:', cartSchema);

// Check what shipping options are used across all carts
const shippingOpts = db.prepare('SELECT DISTINCT shipping_option, shipping_cost FROM carts WHERE shipping_option IS NOT NULL').all();
console.log('\nShipping options in use:', shippingOpts);

// Also check orders for shipping methods/costs
const orderShipping = db.prepare('SELECT DISTINCT shipping_method, shipping_cost FROM orders').all();
console.log('\nOrder shipping methods:', orderShipping);

db.close();
